/**
 *  1. 修改 alert rule 表结构
 *  2. 修改 alert rule 导入导出表头信息
 */

ALTER TABLE  `alert_rule`
MODIFY COLUMN `summary` varchar(512) NOT NULL DEFAULT '' COMMENT '告警摘要',
MODIFY COLUMN `description` varchar(512) NOT NULL DEFAULT '' COMMENT '告警详细描述',
MODIFY COLUMN `receiver` varchar(64) NOT NULL DEFAULT '',
MODIFY COLUMN `method` varchar(256) NOT NULL DEFAULT '' COMMENT 'receiver 不为空时，必填',
ADD COLUMN `auto_expired` int(1) NOT NULL DEFAULT 1 COMMENT '默认：1\r\n1：开启自动失效判断\r\n0：关闭自动失效判断',
ADD COLUMN `sched_enable` int(1) NOT NULL DEFAULT 0 COMMENT '默认：0\r\n1：开启\r\n0：关闭',
ADD COLUMN `sched_days` varchar(64) NOT NULL DEFAULT '1,2,3,4,5,6,7' COMMENT '默认："1,2,3,4,5,6,7"\r\n多个逗号分隔\r\n例：1,2,3,4,5,6,7\r\nsched_enable = 1 时，不能为空',
ADD COLUMN `sched_stime` varchar(64) NOT NULL DEFAULT '00:00' COMMENT '默认：00:00',
ADD COLUMN `sched_etime` varchar(64) NOT NULL DEFAULT '23:59' COMMENT '默认：23:59',
ADD COLUMN `notify_active` int(1) NOT NULL DEFAULT 1 COMMENT 'active通知开关\r\n默认：1\r\n1：开启\r\n0：关闭',
ADD COLUMN `notify_expired` int(1) NOT NULL DEFAULT 1 COMMENT '默认：1\r\n1：开启\r\n0：关闭',
ADD COLUMN `trb_shot` text NOT NULL;

REPLACE INTO `sys_config`(`id`, `param_key`, `param_value`, `status`, `remark`) VALUES (NULL, 'rule_export_header', '{\"cn\":{\"*告警规则名称\":\"告警规则名称(必填) \\n示例: cpuAlert\",\"*告警类型\":\"告警类型(必填) 可选:1: Metrics 2:Logs 3:SNMP TRAP \\n示例: 1\",\"执行周期\":\"执行周期 默认值:0，单位:s 不小于 15 当 < 15, 则为 Scrape interval \\n示例: 30\",\"超时时间\":\"执行周期超时时间 默认值:0，单位:s 不小于 15 当 < 15, 则为 Scrape timeout \\n示例: 30\",\"*运算表达式\":\"运算表达式(必填) \\n示例: 100-(avg(irate(node_cpu_seconds_total{mode=\'idle\'}[5m])) by(instance)* 100)\",\"*比较符号\":\"比较符号(必填) 可选: >,<,<=,>=,==,!= \\n示例: >\",\"*阈值\":\"阈值(必填) \\n示例: 10\",\"*单位\":\"单位(必填) 可选: \\nMisc: none,short,percent(0-100),percent(0.0-1.0),local format\\nData: bits,bytes,kilobytes,megabytes,gigabytes,terabytes,petabytes\\nDataRate: packets/sec,bits/sec,bytes/sec,kilobytes/sec,kilobits/sec,megabytes/sec,megabits/sec,gigabytes/sec,gigabits/sec,terabytes/sec,terabits/sec,petabytes/sec,petabits/sec\\nTime: Hertz(1/s),nanoseconds(ns),microseconds(us),milliseconds(ms),seconds(s),minutes(m),hours(h),days(d),YYYY-MM-DD HH:mm:ss,MM/DD/YYYY h:mm:ss a \\n示例: short\",\"*持续时间\":\"持续时间(必填),默认单位（秒） \\n示例:60\",\"*告警级别\":\"告警级别(必填) 可选 P1、P2、P3 \\n示例: P1\",\"*告警摘要\":\"告警摘要(必填) \\n示例: cpu告警\",\"告警详细描述\":\"告警详细描述 \\n示例: cpu使用率超过10%的告警规则\",\"告警通知人\":\"告警通知人，多个使用逗号分隔 \\n示例: admin / admin,root\",\"通知方式\":\"告警通知方式，告警通知人不为空时，必填.多个使用逗号分隔 \\n示例: email / email,telephone\",\"告警状态\":\"告警状态，默认开启 开启：1 关闭：0 \\n示例:1\",\"自动失效\":\"是否自动失效 默认开启 开启：1 关闭：0 \\n示例:1\",\"定时\":\"定时是否开启 默认：关闭  1：开启 0：关闭 \\n示例:1\",\"定时开启定义\":\"定时开启天（星期几）定时开启时必填, 默认：1,2,3,4,5,6,7,多个逗号分隔, 例：1,2,3 \\n示例: 1,2,3,4,6\",\"开始时间\":\"开始时间 定时开启时必填,默认：00:00 \\n示例: 06:30\",\"关闭时间\":\"关闭时间 定时开启时必填,默认：23:59 \\n示例: 20:30\",\"告警激活通知\":\"告警激活通知开关 默认：开启 1：开启  0：关闭 \\n示例:1\",\"告警失效通知\":\"告警失效通知开关 默认：开启 1：开启  0：关闭 \\n示例:1\",\"故障排查\":\"故障排查描述信息 \\n示例:排查日志信息....\"},\"en\":{\"*Alert name\":\"Alert rule name (required) \\nExample: cpuAlert\",\"*Alert type\":\"Alert type (required) option: 1: metrics 2: logs 3: SNMP TRAP \\nExample: 1\",\"Execution cycle\":\"Performance Cycle Default: 0, unit: S is not less than 15 When <15, Scrape Interval \\nExample: 30\",\"Timeout\":\"Perform cycle timeout time default value: 0, unit: S is not less than 15 When <15, SCRAPE TIMEOUT \\nExample: 30\",\"*Expr\":\"Operation expression (required) \\nExample: 100-(avg(irate(node_cpu_seconds_total{mode=\'idle\')[5m])) by(instance)* 100)\",\"*Operator\":\"Operation symbol (required) Optional: >,<,<=,>=,==,!= \\nExample:>\",\"*Threshold\":\"Threshold (required) \\nExample: 10\",\"*Unit\":\"Unit (required) Optional: \\nMisc: none,short,percent(0-100),percent(0.0-1.0),local format\\nData: bits,bytes,kilobytes,megabytes,gigabytes,terabytes,petabytes\\nDataRate: packets/sec,bits/sec,bytes/sec,kilobytes/sec,kilobits/sec,megabytes/sec,megabits/sec,gigabytes/sec,gigabits/sec,terabytes/sec,terabits/sec,petabytes/sec,petabits/sec\\nTime: Hertz(1/s),nanoseconds(ns),microseconds(us),milliseconds(ms),seconds(s),minutes(m),hours(h),days(d),YYYY-MM-DD HH:mm:ss,MM/DD/YYYY h:mm:ss a \\nExample:short\",\"*Last\":\"Last (required), the default unit (seconds) \\nExample: 60\",\"*Severity\":\"Alert severity (required) optional P1, P2, P3 \\nExample: P1\",\"*Summary\":\"Alert summary \\nExample: Cpu warning\",\"Description\":\"Alert description \\nExample: Alarm rule for cpu usage exceeding 10%\",\"Receiver\":\"Alert receiver, separated by commas \\nExample: admin / admin,root\",\"Notification method\":\"Alarm notification method. When the receiver is not empty, it is required. Multiple use commas to separate \\nExample: email / email,telephone\",\"State\":\"Alarm status, the default enablement: 1 Close: 0 \\nExample: 1\",\"Automatic expired\":\"Whether automatic expired defaults to turn on: 1 Turn off: 0 \\nExample: 1\",\"Schedule\":\"schedule to turn on the default: Close 1: Open 0: Close \\nExample: 1\",\"Schedule days config\":\"schedule open day (week) Timer is turned on, default: 1,2,3,4,5,6,7 multiple comma separation \\nExample: 1,2,3,4,6\",\"Schedule start time\":\"Schedule start time is required when schedule is open, Default: 00:00 \\nExample: 06:30\",\"Schedule close time\":\"Schedule close time is required when schedule is open, default: 23: 59 \\nExample: 20:30\",\"Alarm activate notification\":\"Alarm activate notification switch Default: Open 1: Open 0: Close \\nExample: 1\",\"Alarm expired notification\":\"Alarm expired notification Switch Default: Open 1: Open 0: Close \\nExample: 1\",\"Trouble shooting\":\"Trouble shooting Description Information \\nExample: Check Log Information ....\"}}', 1, NULL);

